class GymMember {protected int sessions;public GymMember(String id,int fee){if(id==null||id.trim().length()<4||fee<=0)throw new IllegalArgumentException();}public void attendSession(){sessions++;}public String displayInfo(){return "Standard | Sessions: "+sessions;}}
class PremiumMember extends GymMember {private String trainer;public PremiumMember(String id,int fee,String t){super(id,fee);trainer=t;}public String getTrainerName(){return trainer;}@Override public String displayInfo(){return "Premium | Trainer: "+trainer+" | Sessions: "+sessions;}}
public class Problem4_MonthlyAttendanceAnnouncer {static String batchPrint(GymMember[] members){StringBuilder b=new StringBuilder();for(GymMember m:members){if(b.length()>0)b.append(" | ");b.append(m.displayInfo());if(m instanceof PremiumMember){PremiumMember p=(PremiumMember)m;b.append(" [Trainer via downcast: ").append(p.getTrainerName()).append("]");}}return b.toString();}public static void main(String[]x){System.out.println(batchPrint(new GymMember[]{new GymMember("MEM6",1000),new PremiumMember("MEM7",2000,"Coach Riya")}));}}